def evaluate(current_reputation, observation, my_history, round_num):
    # observation is a dict with key 'action': 'cooperate' or 'defect'
    action = observation['action']
    # Base reputation update: +1 for cooperate, -1 for defect
    if action == 'cooperate':
        base = 1.0
    else:  # 'defect'
        base = -1.0
    # Weighted average: give higher weight to recent action, lower to past reputation
    new_rep = 0.9 * current_reputation + 0.1 * base
    # Clamp to valid range
    return max(-1.0, min(1.0, new_rep))

